        source: "https://www.chinachristiantimes.com/news/39266/",
        excerpt: "其实这部影片向我们传达了一个非常重要的道理，那就是：“我们固然有很多地方不如别人，但我们所拥有的一些东西也是最独特的”。令人唏嘘的是我们常常聚焦于自己的瑕疵和缺陷，而忽略了上帝让我们去发挥的那一部分。我们花费了太多的时间去比较、去嫉妒、去自怜、去痛苦，却花了太少的时间去发挥上帝给我们的长处、恩赐、技巧还有智慧。在这个世界上，许多人都活在纠结的痛苦之中，放大自己的问题，不去面对自己的问题，向别人倾诉自己的痛苦，却不去忘记痛苦，走出痛苦。"
