        source: "https://www.chinachristiantimes.com/news/39119/",
        excerpt: "我们不禁会问，为何满怀期望的人生总是充满无奈？为何每个人到头来得到的答案都是“人生无意义”的虚无感呢？我想《白日烟火》对人物的精心刻画，正是告诉了我们答案，那便是在被罪所辖制的人生中，其本质不过是如烟花般短暂的绽放后，剩下的就只有寂静的虚无。使徒保罗也如此向我们证明说：“受造之物服在虚空之下，不是自己愿意，乃是因那叫他如此的。”由此我们看明了，人生的意义正如电影中向我们呈现的那样：人活着若是不认识上帝，不相信基督的救赎之恩，那么生命本身所有的便只剩下张自力式的荒诞、吴志贞式的虚无与丈夫梁志军式的活在死亡的笼罩之中。"
